const startAwakeningRun = `-- name: StartAwakeningRun :one

INSERT INTO awakening_run (user_id, attempt_no)
VALUES (
  $1,
  1 + (SELECT count(*) FROM awakening_run
       WHERE user_id = $1 AND finished_at IS NOT NULL)
)
RETURNING id, user_id, attempt_no, stage, route, navigator, energy_profile, talent, lens_choice, challenge_choice, archive_attempts, observer_question, created_at, updated_at, finished_at, title
`

// ── 觉醒协议 ──────────────────────────────────────────────────────────────
// 开一趟。**先落库再做题**：一次中途退出也留下一行（finished_at 为空），
// 而「她走到哪一屏就走开了」本身就是数据（铁律④）。
//
// attempt_no 在插入时由子查询算出来并写死，不在读取时现数 —— 现数会让两个
// 并发的重复 POST 都读到同一个「已完成 1 次」，于是都写成「第 2 次」。
// 部分唯一索引 awakening_run_open_idx 另外保证同一个人最多只有一趟没走完。
func (q *Queries) StartAwakeningRun(ctx context.Context, userID uuid.UUID) (AwakeningRun, error) {
	row := q.db.QueryRow(ctx, startAwakeningRun, userID)
	var i AwakeningRun
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.AttemptNo,
		&i.Stage,
		&i.Route,
		&i.Navigator,
		&i.EnergyProfile,
		&i.Talent,
		&i.LensChoice,
		&i.ChallengeChoice,
		&i.ArchiveAttempts,
		&i.ObserverQuestion,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.FinishedAt,
		&i.Title,
	)
	return i, err
}
